import { useEffect } from "react";
import { refreshStock } from "./stock";

type StockWatcherProps = {
  slug: string;
};

export function StockWatcher({ slug }: StockWatcherProps) {
  useEffect(() => {
    console.log(`start watching ${slug}`);
    const id = setInterval(() => refreshStock(slug), 30_000);

    return () => {
      console.log(`stop watching ${slug}`);
      clearInterval(id);
    };
  }, [slug]);

  return <p>Stock updates every 30 seconds.</p>;
}

