import { useEffect, useState } from "react";
import type { ProductSummary } from "./types";

type ProductSearchProps = {
  products: ProductSummary[];
};

export function ProductSearch({ products }: ProductSearchProps) {
  const [query, setQuery] = useState("");
  const [visible, setVisible] = useState(products);

  useEffect(() => {
    const q = query.toLowerCase();
    setVisible(products.filter((p) => p.name.toLowerCase().includes(q)));
  }, [products, query]);

  console.log(`render: query "${query}", showing ${visible.length}`);

  return (
    <div>
      <input aria-label="Search products" value={query} onChange={(e) => setQuery(e.target.value)} />
      <ul>
        {visible.map((p) => (
          <li key={p.slug}>{p.name}</li>
        ))}
      </ul>
    </div>
  );
}

