import type { ComponentProps } from "react";

type SearchFieldProps = ComponentProps<"input"> & {
  label: string;
};

export function SearchField({ label, ref, ...inputProps }: SearchFieldProps) {
  return (
    <label className="search-field">
      <span>{label}</span>
      <input ref={ref} type="search" {...inputProps} />
    </label>
