}

// src/features/products/ProductSearchBar.tsx
import { useRef, useState } from "react";
import { SearchField } from "@/components/ui/SearchField";

export function ProductSearchBar() {
  const [query, setQuery] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);

  function handleClear() {
    setQuery("");
    inputRef.current?.focus();
  }

  return (
    <div className="search-bar">
      <SearchField
        ref={inputRef}
        label="Search products"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
      />
      <button type="button" onClick={handleClear}>
        Clear
      </button>
    </div>
  );
}

import { useEffect, useRef, useState } from "react";

type AddToCartButtonProps = {
  onAdd: () => void;
};

export function AddToCartButton({ onAdd }: AddToCartButtonProps) {
  const [justAdded, setJustAdded] = useState(false);
  const timerId = useRef<number | undefined>(undefined);

  function handleClick() {
    onAdd();
    setJustAdded(true);
    clearTimeout(timerId.current);
    timerId.current = setTimeout(() => setJustAdded(false), 2000);
  }

  useEffect(() => {
    return () => clearTimeout(timerId.current);
  }, []);

  return (
    <button type="button" onClick={handleClick}>
      {justAdded ? "Added" : "Add to cart"}
    </button>
  );
}

import { useEffect, useRef, useState } from "react";
import { SearchField } from "@/components/ui/SearchField";

export function HeaderSearch() {
  const [query, setQuery] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const controller = new AbortController();

    window.addEventListener(
      "keydown",
      (event) => {
        if (event.key !== "/" || event.target !== document.body) return;
        event.preventDefault();
        inputRef.current?.focus();
      },
      { signal: controller.signal },
    );

    return () => controller.abort();
  }, []);

  return (
    <SearchField
      ref={inputRef}
      label="Search (press /)"
      value={query}
      onChange={(e) => setQuery(e.target.value)}
    />
  );
}

import { useSyncExternalStore } from "react";

function subscribe(onChange: () => void) {
  window.addEventListener("online", onChange);
  window.addEventListener("offline", onChange);
  return () => {
    window.removeEventListener("online", onChange);
    window.removeEventListener("offline", onChange);
  };
}

export function useOnlineStatus() {
  return useSyncExternalStore(subscribe, () => navigator.onLine);
}

// src/components/ui/OfflineBanner.tsx
import { useOnlineStatus } from "@/hooks/useOnlineStatus";

export function OfflineBanner() {
  const isOnline = useOnlineStatus();
  console.log(`render: ${isOnline ? "online" : "offline"}`);

  if (isOnline) return null;
  return <p role="status">You're offline. Changes will save when you reconnect.</p>;
}

import { useEffect, useEffectEvent, useRef } from "react";

type LoadMoreSentinelProps = {
  onVisible: () => void;
};

export function LoadMoreSentinel({ onVisible }: LoadMoreSentinelProps) {
  const ref = useRef<HTMLDivElement>(null);
  const handleVisible = useEffectEvent(onVisible);

  useEffect(() => {
    const node = ref.current;
    if (!node) return;

    const observer = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) handleVisible();
    });
    observer.observe(node);

    return () => observer.disconnect();
  }, []);

  return <div ref={ref} aria-hidden="true" />;
}

steps.body:
The patterns from the previous part repeat. Three components need to know if the screen is narrow. Two need to remember a choice in `localStorage`. A search box, a filter, and an address lookup all need to wait until you stop typing. Copying the same effect into each one copies its bugs too, and a fix has to be made in every copy. A custom hook gives that logic one name, one place to fix it, and one place to test it.

## A function whose name starts with use

A **custom hook** is a function whose name starts with `use` and that calls other hooks. That's all it is. React doesn't register it or treat it specially. The name is a promise to the people and tools reading your code: the rules of hooks apply inside it and wherever it's called, so it's only called at the top level of a component or of another hook, never inside a condition or a loop. The linter relies on the `use` prefix to check those rules.

Here's `useMediaQuery`, which answers whether a CSS media query matches right now, built on `useSyncExternalStore` from the previous part:

```tsx
export function useMediaQuery(query: string): boolean {
  return useSyncExternalStore(
    (onChange) => {
      const list = window.matchMedia(query);
      list.addEventListener("change", onChange);
      return () => list.removeEventListener("change", onChange);
    },
    () => window.matchMedia(query).matches,
  );
}
```

`window.matchMedia` takes the same text you'd write after `@media` in CSS, and its `change` event fires when the answer flips. Now any component can write `const isNarrow = useMediaQuery("(max-width: 40rem)")` and render a different layout. React subscribes again whenever it gets a different `subscribe` function, and the React Compiler in your project keeps this one the same until `query` changes.

## Saving a choice: useLocalStorage

The first example keeps a value in state and saves it to `localStorage`, so the shop remembers whether you like products in a grid or a list. It reads storage in a **lazy initial state**: `useState(() => readSaved(key, initialValue))` passes a function, which React calls only on the first render. Passing `readSaved(key, initialValue)` itself would read storage on every render and throw the answer away each time after the first.

Both reading and writing are wrapped in `try`, because storage can fail: it throws when it's full or when the browser has it turned off, and `JSON.parse` throws on text that isn't valid JSON. When that happens, the hook falls back to the starting value and keeps the choice in memory only.

## Hooks share logic, not state

Two components that both call `useLocalStorage("product-view", "grid")` don't share one value. Each call runs the hook's code inside that component, so each component gets its own `useState`. Change the view in one, and the other keeps showing the old one until it mounts again. When several components need one shared value, lift it up to a common parent or keep it in a store, which the next lesson covers. Hooks built on `useSyncExternalStore`, like `useOnlineStatus`, look shared because they all read one source, but that source lives outside React.

## Typing a hook with generics

`useLocalStorage<T>` has a **type parameter**: `T` stands for whatever type the caller uses, so one hook works for all of them. `useLocalStorage("product-view", "grid")` gives back a string, and `useLocalStorage("recently-viewed", [] as string[])` a list of strings. You can name `T` yourself, as `useLocalStorage<"grid" | "list">("product-view", "grid")` does, to allow only those two words. Returning `[value, save] as const` tells TypeScript the result is a pair, the value first and the function second, like what `useState` returns.

One honest limit: `JSON.parse(saved) as T` trusts that what's in storage has the right shape, and an older version of your app may have saved something else. The Calling APIs From React lesson shows how to check data like this with a schema.

