import { useState } from "react";

function readSaved<T>(key: string, fallback: T): T {
  try {
    const saved = localStorage.getItem(key);
    return saved === null ? fallback : (JSON.parse(saved) as T);
  } catch {
    return fallback;
  }
}

export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState(() => readSaved(key, initialValue));

  function save(next: T) {
    setValue(next);
    try {
      localStorage.setItem(key, JSON.stringify(next));
    } catch {
      // Storage is full or turned off: the value lives in memory only.
    }
  }

  return [value, save] as const;
}

import { useEffect, useState } from "react";

export function useDebouncedValue<T>(value: T, delayMs = 300): T {
  const [debounced, setDebounced] = useState(value);

  useEffect(() => {
    const id = setTimeout(() => setDebounced(value), delayMs);
    return () => clearTimeout(id);
  }, [value, delayMs]);

  return debounced;
}

// src/features/products/ProductSearch.tsx
import { useEffect, useState } from "react";
import { SearchField } from "@/components/ui/SearchField";
import { useDebouncedValue } from "@/hooks/useDebouncedValue";

export function ProductSearch() {
  const [query, setQuery] = useState("");
  const debouncedQuery = useDebouncedValue(query, 300);

  useEffect(() => {
    console.log(`search for "${debouncedQuery}"`);
  }, [debouncedQuery]);

  return (
    <SearchField
      label="Search products"
      value={query}
      onChange={(e) => setQuery(e.target.value)}
    />
  );
}

import { useLayoutEffect, useRef, useState, type ReactNode } from "react";

type TooltipProps = {
  children: ReactNode;
};

export function Tooltip({ children }: TooltipProps) {
  const ref = useRef<HTMLDivElement>(null);
  const [placement, setPlacement] = useState<"above" | "below">("above");

  useLayoutEffect(() => {
    const box = ref.current?.getBoundingClientRect();
    if (box && box.top < 0) setPlacement("below");
  }, []);

  return (
    <div ref={ref} role="tooltip" className={`tooltip tooltip-${placement}`}>
      {children}
    </div>
  );
}

import { useEffect, useId, useRef, type ReactNode } from "react";

type DialogProps = {
  open: boolean;
  onClose: () => void;
  title: string;
  children: ReactNode;
};

export function Dialog({ open, onClose, title, children }: DialogProps) {
  const ref = useRef<HTMLDialogElement>(null);
  const titleId = useId();

  useEffect(() => {
    const dialog = ref.current;
    if (!dialog) return;
    if (open && !dialog.open) dialog.showModal();
    if (!open && dialog.open) dialog.close();
  }, [open]);

  return (
    <dialog ref={ref} aria-labelledby={titleId} onClose={onClose}>
      <h2 id={titleId}>{title}</h2>
      {children}
      <form method="dialog">
        <button>Close</button>
      </form>
    </dialog>
  );
}
